'use client';
/**
 * 推荐职位地图：Google 中文底图（Leaflet 加载瓦片，不需要 API Key；演示用，国内需要能访问 Google），
 * 每个城市一个气泡：「[公司] 城市 · n 个职位」；意向城市即使暂无职位也标出来。点气泡筛选该城市。
 */
import React, { useEffect, useRef } from 'react';
import 'leaflet/dist/leaflet.css';

export interface CityPin { city: string; lat: number; lng: number; jobs: number; top?: string; intent: boolean }

export default function JobMap({ pins, selected, onSelect }: { pins: CityPin[]; selected: string | null; onSelect: (city: string | null) => void }) {
  const el = useRef<HTMLDivElement>(null);
  const mapRef = useRef<any>(null);
  const layerRef = useRef<any>(null);
  const LRef = useRef<any>(null);

  useEffect(() => {
    let alive = true;
    (async () => {
      const L = (await import('leaflet')).default;
      if (!alive || !el.current || mapRef.current) return;
      LRef.current = L;
      const map = L.map(el.current, { zoomControl: false, attributionControl: true }).setView([31.5, 114], 5);
      L.tileLayer('https://mt{s}.google.com/vt/lyrs=m&hl=zh-CN&gl=CN&x={x}&y={y}&z={z}', {
        subdomains: '0123', maxZoom: 18, attribution: '地图数据 © Google',
      }).addTo(map);
      L.control.zoom({ position: 'bottomleft' }).addTo(map);
      mapRef.current = map;
      layerRef.current = L.layerGroup().addTo(map);
      draw();
    })();
    return () => { alive = false; mapRef.current?.remove(); mapRef.current = null; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const draw = () => {
    const L = LRef.current, map = mapRef.current, layer = layerRef.current;
    if (!L || !map || !layer) return;
    layer.clearLayers();
    const bounds: [number, number][] = [];
    for (const p of pins) {
      const active = selected === p.city;
      const html = `<div class="jm-pin ${active ? 'on' : ''} ${p.jobs ? '' : 'empty'}">
        ${p.top ? `<span class="jm-logo">${p.top.slice(0, 1)}</span>` : ''}
        <span>${p.jobs ? `${p.top ? `${p.top}${p.jobs > 1 ? '等' : ''} · ` : ''}${p.city} · ${p.jobs} 个职位` : `${p.city} · 意向城市`}</span>
        ${p.intent ? '<span class="jm-star">★</span>' : ''}
      </div>`;
      const m = L.marker([p.lat, p.lng], { icon: L.divIcon({ html, className: 'jm-wrap', iconSize: undefined as any, iconAnchor: [0, 16] }) });
      m.on('click', () => onSelect(active ? null : p.city));
      m.addTo(layer);
      bounds.push([p.lat, p.lng]);
    }
    if (selected) {
      const p = pins.find((x) => x.city === selected);
      if (p) map.flyTo([p.lat, p.lng], 10, { duration: 0.8 });
    } else if (bounds.length) {
      map.fitBounds(bounds, { padding: [70, 70], maxZoom: 7 });
    }
  };

  useEffect(() => { draw(); /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, [pins, selected]);

  return (
    <div style={{ position: 'relative', width: '100%', height: '100%', minHeight: 360 }}>
      <style>{`
        .jm-wrap { background: none; border: none; }
        .jm-pin { display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; background: #fff; border-radius: 999px; padding: 5px 12px 5px 6px; font: 600 12.5px/1 -apple-system, "PingFang SC", sans-serif; color: #1f2333; box-shadow: 0 3px 12px rgba(0,0,0,.18); border: 1.5px solid #fff; cursor: pointer; transform: translateY(-50%); }
        .jm-pin.empty { color: #6b7086; padding-left: 12px; }
        .jm-pin.on { background: #5b4ff0; color: #fff; border-color: #5b4ff0; z-index: 1000; }
        .jm-logo { width: 20px; height: 20px; border-radius: 50%; background: #eeedff; color: #5b4ff0; display: inline-flex; align-items: center; justify-content: center; font-size: 11px; }
        .jm-pin.on .jm-logo { background: #fff; }
        .jm-star { color: #f5a623; }
      `}</style>
      <div ref={el} style={{ position: 'absolute', inset: 0, borderRadius: 16, overflow: 'hidden' }} />
    </div>
  );
}
/**
 * AI 职业访谈 · 推荐职位：从企业平台（companydata，只读）的真实校招职位里，按报告的岗位方向挑出最匹配的，
 * 配不上的用报告里的「代表性企业」补成推荐企业卡片。结果缓存在 career_sessions.jobs。
 */
import { federation } from '@/lib/federation/clients';
import { careerComplete } from './interview';

/** 主要城市坐标（地图气泡用） */
export const CITY_COORDS: Record<string, [number, number]> = {
  北京: [39.9042, 116.4074], 上海: [31.2304, 121.4737], 深圳: [22.5431, 114.0579], 广州: [23.1291, 113.2644],
  杭州: [30.2741, 120.1551], 南京: [32.0603, 118.7969], 苏州: [31.2989, 120.5853], 无锡: [31.4912, 120.3119],
  常州: [31.8107, 119.9740], 合肥: [31.8206, 117.2272], 成都: [30.5728, 104.0668], 重庆: [29.5630, 106.5516],
  武汉: [30.5928, 114.3055], 西安: [34.3416, 108.9398], 天津: [39.3434, 117.3616], 厦门: [24.4798, 118.0894],
  长沙: [28.2282, 112.9388], 郑州: [34.7466, 113.6254], 青岛: [36.0671, 120.3826], 济南: [36.6512, 117.1201],
  宁波: [29.8683, 121.5440], 东莞: [23.0207, 113.7518], 佛山: [23.0215, 113.1214], 珠海: [22.2710, 113.5767],
  惠州: [23.1115, 114.4152], 盐城: [33.3476, 120.1633], 宁德: [26.6657, 119.5480], 枣庄: [34.8107, 117.3237],
  大连: [38.9140, 121.6147], 沈阳: [41.8057, 123.4315], 哈尔滨: [45.8038, 126.5350], 福州: [26.0745, 119.2965],
  昆明: [25.0389, 102.7183], 贵阳: [26.6470, 106.6302], 南昌: [28.6820, 115.8579], 石家庄: [38.0428, 114.5149],
  香港: [22.3193, 114.1694],
};
export const HOT_CITIES = ['北京', '上海', '深圳', '杭州', '广州', '南京', '成都', '武汉'];

export function normCity(raw?: string | null): string | null {
  const s = String(raw || '').replace(/(市|特别行政区)$/, '').trim();
  if (!s) return null;
  return Object.keys(CITY_COORDS).find((c) => s.startsWith(c) || s.includes(c)) || s;
}

export interface MatchedJob {
  id: number;
  company: string;
  title: string;
  city: string | null;
  location: string | null;
  func: string | null;
  type: string | null;
  season: string | null;
  grad: string | null;
  salary: string | null;
  link: string | null;
  match: number;
  reason: string;
  role: string;
}

export interface RecommendedCompany { name: string; role: string; reason: string }

/** 从文本里拆出企业名：「宝洁、欧莱雅等外企快消，字节跳动（上海）」→ [宝洁, 欧莱雅, 字节跳动] */
function companiesFrom(text: string): string[] {
  return String(text || '')
    .replace(/[（(][^）)]*[）)]/g, '')
    .split(/[、，,；;\/]|等|以及|和/)
    .map((s) => s.replace(/^(如|例如|比如|包括)/, '').trim())
    .filter((s) => s.length >= 2 && s.length <= 12 && !/企业|公司类|行业|机构|方向|大厂|头部|一线|中大型|新锐|知名|互联网|外企|国企|央企/.test(s));
}

export async function matchJobs(report: any, profile: any): Promise<{ jobs: MatchedJob[]; companies: RecommendedCompany[]; cost: number }> {
  const db = federation.companydata;
  const roles: any[] = Array.isArray(report?.roles) ? report.roles : [];
  let jobs: MatchedJob[] = [];
  let cost = 0;

  if (db && roles.length) {
    const { data } = await db.from('jobs')
      .select('id, institute_or_company_name, title_cn, name, job_function, job_type, recruit_season, city, location, province, graduation_year, salary_description, internship_salary_min, internship_salary_max, salary_unit, link, application_website, major_requirement, skill_labels, status, if_delete')
      .limit(2000);
    const pool = (data || []).filter((j: any) => j.status !== 'closed' && !j.if_delete);
    if (pool.length) {
      const brief = pool.map((j: any) => `${j.id}|${j.institute_or_company_name}|${j.title_cn || j.name}|${j.job_function || ''}|${j.job_type || ''}|${normCity(j.city) || ''}|${String(j.major_requirement || '').slice(0, 40)}`).join('\n');
      const { data: picked, cost: c } = await careerComplete<{ matches: Array<{ id: number; match: number; reason: string; role: string }> }>(
        'jobs',
        `你在为一位求职者（以应届生为主）从真实的校招职位库里挑选匹配的职位。只挑真正对口的，不要凑数；每个职位给 0-100 的匹配度和一句 30 字以内的理由（要结合求职者的经历），并注明对应报告里的哪个岗位方向。
只输出 JSON：{"matches": [{"id": 职位 id, "match": 匹配度, "reason": "理由", "role": "对应的岗位方向"}]}，按匹配度从高到低，最多 15 个；匹配度低于 55 的不要。`,
        `求职者画像：${profile?.headline || ''}；关键词：${(profile?.keywords || []).join('、')}
报告推荐的岗位方向：${roles.map((r: any) => `${r.title}（${r.why || ''}）`).join('；')}
意向城市：${report?.criteria?.location || '未提及'}

职位库（id|公司|职位|职能|类型 graduate=校招 intern=实习 program=项目|城市|专业要求）：
${brief}`,
        { temperature: 0.2 },
      );
      cost += c;
      const byId = new Map(pool.map((j: any) => [Number(j.id), j]));
      jobs = (picked?.matches || [])
        .filter((m) => byId.has(Number(m.id)))
        .map((m) => {
          const j: any = byId.get(Number(m.id));
          const sal = j.salary_description || (j.internship_salary_min ? `${j.internship_salary_min}${j.internship_salary_max ? `-${j.internship_salary_max}` : ''}${j.salary_unit ? `/${j.salary_unit}` : ''}` : null);
          return {
            id: j.id, company: j.institute_or_company_name, title: j.title_cn || j.name,
            city: normCity(j.city) || normCity(j.province), location: j.location || null,
            func: j.job_function, type: j.job_type, season: j.recruit_season, grad: j.graduation_year ? String(j.graduation_year).slice(0, 20) : null,
            salary: sal ? String(sal).slice(0, 40) : null, link: j.application_website || j.link || null,
            match: Math.max(0, Math.min(100, Math.round(Number(m.match) || 0))), reason: String(m.reason || ''), role: String(m.role || ''),
          };
        });
    }
  }

  // 报告里的代表性企业：职位库里没有的，补成推荐企业卡片
  const have = new Set(jobs.map((j) => j.company));
  const companies: RecommendedCompany[] = [];
  for (const r of roles) {
    for (const name of companiesFrom(r.companies)) {
      if (have.has(name) || companies.some((c) => c.name === name)) continue;
      companies.push({ name, role: r.title, reason: r.why || '' });
    }
  }
  return { jobs, companies: companies.slice(0, 12), cost };
}
