/**
 * 访谈与报告用哪家模型（这个功能可切国内模型；平台其余部分仍只用 Gemini / OpenAI）：
 *   CAREER_LLM 未设或 = openai   → OpenAI GPT-5.6 Luna（便宜、中文好），失败回落默认模型
 *   CAREER_LLM = deepseek          → DeepSeek，走 OpenAI 兼容接口：
 *                                    DEEPSEEK_API_KEY + DEEPSEEK_BASE_URL（官方），没有就用 DASHSCOPE_API_KEY + DASHSCOPE_BASE_URL；
 *                                    模型名 DEEPSEEK_MODEL（默认 deepseek-v3）
 * 语音识别 / 朗读另走 OpenAI（DeepSeek 没有语音能力）。
 */
export const CAREER_MODEL_ID = 'gpt-56-luna';
export function careerProvider(): 'openai' | 'deepseek' {
  return (process.env.CAREER_LLM || '').toLowerCase() === 'deepseek' ? 'deepseek' : 'openai';
}

async function deepseekComplete(messages: Array<{ role: 'system' | 'user'; content: string }>, opts: { temperature?: number; maxTokens?: number }) {
  const apiKey = process.env.DEEPSEEK_API_KEY || process.env.DASHSCOPE_API_KEY;
  const baseURL = process.env.DEEPSEEK_API_KEY
    ? (process.env.DEEPSEEK_BASE_URL || 'https://api.deepseek.com/v1')
    : (process.env.DASHSCOPE_BASE_URL || 'https://dashscope.aliyuncs.com/compatible-mode/v1');
  const model = process.env.DEEPSEEK_MODEL || (process.env.DEEPSEEK_API_KEY ? 'deepseek-chat' : 'deepseek-v3');
  if (!apiKey) throw new Error('未配置 DeepSeek 的 API Key');
  const OpenAI = (await import('openai')).default;
  const client = new OpenAI({ apiKey, baseURL });
  const res = await client.chat.completions.create({
    model, messages, temperature: opts.temperature, max_tokens: opts.maxTokens,
    response_format: { type: 'json_object' },
  });
  return { text: res.choices[0]?.message?.content || '', usage: res.usage as any, model };
}

/** 今天的日期与当前校招季（时间线、届别要按这个算，不然模型会写出已经过去的时间） */
export function todayContext(): string {
  const d = new Date(Date.now() + 8 * 3600_000);   // 北京时间
  const y = d.getUTCFullYear(), m = d.getUTCMonth() + 1;
  // 秋招在每年 7～12 月，面向次年毕业的一届；春招在 2～5 月，面向当年毕业的一届
  const season = m >= 7 ? `${y} 年秋招（主要面向 ${String(y + 1).slice(2)} 届）` : m <= 5 ? `${y} 年春招（主要面向 ${String(y).slice(2)} 届），以及 ${String(y + 1).slice(2)} 届的暑期实习招聘` : `${String(y + 1).slice(2)} 届暑期实习与秋招提前批`;
  return `今天是 ${y} 年 ${m} 月 ${d.getUTCDate()} 日（北京时间），当前招聘季：${season}。所有时间建议都要从今天往后排，不要写已经过去的时间。`;
}

/** 访谈与报告的模型调用；返回解析好的 JSON 与本次费用 */
export async function careerComplete<T>(stage: string, system: string, user: string, opts: { temperature?: number; maxTokens?: number } = {}) {
  const tracker = new TokenTracker();
  const messages = [{ role: 'system' as const, content: `${system}\n\n${todayContext()}` }, { role: 'user' as const, content: user }];
  const r = careerProvider() === 'deepseek'
    ? await deepseekComplete(messages, { temperature: opts.temperature ?? 0.6, maxTokens: opts.maxTokens })
    : await auditComplete({ modelId: CAREER_MODEL_ID, json: true, temperature: opts.temperature ?? 0.6, maxTokens: opts.maxTokens, messages });
  tracker.track(`career:${stage}`, r.model, r.usage);
  return { data: parseJsonLoose<T>(r.text), cost: tracker.getSummary().total_cost_usd, model: r.model };
}

/** 简历里对访谈有用的部分（去掉空字段，控制长度） */
export function resumeBrief(resume: any): string {
  if (!resume) return '（未提供简历）';
  const pick = {
    name: resume.name, title: resume.title, summary: resume.summary,
    education: (resume.education || []).slice(0, 4),
    experience: (resume.experience || []).slice(0, 6).map((e: any) => ({ company: e.company, title: e.title || e.role, period: e.period, description: String(e.description || '').slice(0, 300) })),
    skills: resume.skills, projects: (resume.projects || []).slice(0, 4), awards: (resume.awards || []).slice(0, 5),
    publications: (resume.publications || []).slice(0, 3).map((p: any) => p.title),
  };
  return JSON.stringify(pick, (_, v) => (v === '' || v == null || (Array.isArray(v) && !v.length) ? undefined : v), 1).slice(0, 6000);
}

/** 读完简历就定好的访谈提纲：每段要问什么、要追问什么 */
export interface InterviewPlanItem { stage: number; focus: string; questions: string[] }

export interface Profile {
  headline: string;
  identity: string;
  level: string;
  strengths: string[];
  keywords: string[];
  competitiveness: string;
  directions: string[];
  /** 开场白：打招呼 + 说明访谈 + 第一段的第一个问题（直接朗读，不再调模型） */
  opening: string;
  plan: InterviewPlanItem[];
}

