/**
 * 访谈录音（照 zhiji-yida 的 lib/audio/recorder 收编，加了「说完自动停」）。
 *
 * - 浏览器录成什么就传什么（webm/opus 或 mp4），服务端转写；不用浏览器自带语音识别（它连 Google，国内用不了）
 * - getUserMedia 只在 HTTPS / localhost 下可用
 * - 自动停：听到声音之后，连续安静 silenceMs 就停；一直没开口 noSpeechMs 后也停（交给页面提示）；最长 maxMs
 */
export type VoiceSupport = 'recorder' | 'none';

export function detectVoiceSupport(): VoiceSupport {
  if (typeof window === 'undefined') return 'none';
  return window.isSecureContext && !!navigator.mediaDevices?.getUserMedia && typeof MediaRecorder !== 'undefined' ? 'recorder' : 'none';
}

export function explainMicError(e: unknown): string {
  if (typeof window !== 'undefined' && !window.isSecureContext) return '这个地址不是 HTTPS，浏览器不给麦克风权限。可以打字回答。';
  const name = (e as { name?: string })?.name || '';
  if (name === 'NotAllowedError' || name === 'SecurityError') return '麦克风权限被拒绝了。可以在浏览器设置里允许，或直接打字回答。';
  if (name === 'NotFoundError') return '没有找到麦克风，可以打字回答。';
  if (name === 'NotReadableError') return '麦克风被其他应用占用了，关掉再试，或打字回答。';
  return '打不开麦克风，可以打字回答。';
}

function pickMime(): string {
  const cands = ['audio/webm;codecs=opus', 'audio/webm', 'audio/mp4', 'audio/ogg;codecs=opus'];
  return cands.find((m) => { try { return MediaRecorder.isTypeSupported(m); } catch { return false; } }) || '';
}

export interface ListenHandle {
  /** 手动停止并拿到音频（太短返回 null） */
  stop(): Promise<Blob | null>;
  /** 丢弃 */
