export interface ListenOptions {
  onLevel?: (v: number) => void;
  /** 自动停（说完了 / 一直没说 / 到时长）时回调，带上音频（没说话为 null）和原因 */
  onAutoStop?: (blob: Blob | null, reason: 'silence' | 'no-speech' | 'max') => void;

/**
 * AI 职业访谈 · 一轮对话（游客可用）
 * POST { sessionId, userText? } → 服务端追加用户发言、生成顾问的下一句并保存
 * 不带 userText = 开场白。返回 { reply, stage, stageLabel, finished, turns }
 */
import { NextResponse } from 'next/server';
import { supabase } from '@/lib/supabase/client';
import { addCost, careerComplete, interviewSystem, LIMITS, loadSession, STAGES, transcriptText, type TurnResult } from '@/lib/career/interview';
export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 60;
export async function POST(req: Request) {
  try {
    const body = await req.json().catch(() => ({}));
    const s = await loadSession(body.sessionId);
    if (!s) return NextResponse.json({ error: '会话不存在' }, { status: 404 });
    if (s.status === 'done') return NextResponse.json({ error: '这次访谈已经结束' }, { status: 400 });
    const transcript: any[] = Array.isArray(s.transcript) ? s.transcript : [];
    const userText = typeof body.userText === 'string' ? body.userText.trim().slice(0, LIMITS.maxUserChars) : '';
    if (transcript.length && !userText) return NextResponse.json({ error: '没有收到你的回答' }, { status: 400 });
    const now = new Date().toISOString();
    if (userText) transcript.push({ role: 'user', text: userText, stage: s.stage, at: now });
    const aiTurns = transcript.filter((t) => t.role === 'ai').length;
    const lastTurn = aiTurns + 1 >= LIMITS.maxTurns;
    const userPrompt = transcript.length
      ? `访谈记录：\n${transcriptText(transcript)}\n\n已提炼要点：${JSON.stringify(s.notes || {})}\n当前在第 ${s.stage} 段（${STAGES[s.stage - 1]?.label}）。${lastTurn ? '这是最后一轮：请感谢对方并结束访谈，finished=true。' : '请给出顾问的下一句。'}`
      : `现在开场：先用一句话打招呼并说明这次访谈的目的（约 10 分钟、帮你理清求职方向、生成职业分析报告），再结合简历问第一段「目标明确」的第一个问题。`;
    // 开场白读完简历时就定好了：直接用，不再等一次模型
    const opening = !transcript.length && typeof s.profile?.opening === 'string' && s.profile.opening.trim() ? s.profile.opening.trim() : '';
    const { data, cost } = opening
      ? { data: { reply: opening, stage: 1, finished: false, notes: {} } as TurnResult, cost: 0 }
      : await careerComplete<TurnResult>('turn', interviewSystem(s.resume, s.profile), userPrompt);
    const reply = String(data?.reply || '').trim() || '抱歉，我刚才没组织好语言。能再说一遍吗？';
    // stage = 这句话里的问题属于第几段；只前进不后退
    const stage = Math.min(5, Math.max(Number(s.stage) || 1, Number(data?.stage) || 1));
    const finished = !!data?.finished || lastTurn;
    transcript.push({ role: 'ai', text: reply, stage, at: new Date().toISOString() });
    await supabase.from('career_sessions').update({
      transcript, stage, turns: aiTurns + 1, status: 'interview',
      notes: { ...(s.notes || {}), ...(data?.notes && typeof data.notes === 'object' ? data.notes : {}) },
      updated_at: new Date().toISOString(),
    }).eq('id', s.id);
    await addCost(s.id, s.cost_usd, cost);
    return NextResponse.json({ reply, stage: finished ? 5 : stage, stageLabel: STAGES[(finished ? 5 : stage) - 1].label, finished, turns: aiTurns + 1, index: transcript.length - 1 });
  } catch (e: any) {
    console.error('[career/turn]', e);
    return NextResponse.json({ error: e?.message || '对话失败' }, { status: 500 });
  }
}
/**
 * AI 职业访谈 · 朗读顾问的话（游客可用）
 * POST { sessionId, index } → audio/mpeg
 * 只朗读会话里第 index 条、且是顾问自己说的话——不接受任意文本，防止被当作免费朗读服务。
 */
import OpenAI from 'openai';
import { supabase } from '@/lib/supabase/client';
import { addCost, LIMITS, loadSession } from '@/lib/career/interview';
export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 60;
const err = (msg: string, status: number) => new Response(JSON.stringify({ error: msg }), { status, headers: { 'Content-Type': 'application/json' } });
export async function POST(req: Request) {
  try {
    const body = await req.json().catch(() => ({}));
    const s = await loadSession(body.sessionId);
    if (!s) return err('会话不存在', 404);
    if ((s.tts_count || 0) >= LIMITS.maxTts) return err('朗读次数用完了', 429);
    const item = (Array.isArray(s.transcript) ? s.transcript : [])[Number(body.index)];
    if (!item || item.role !== 'ai') return err('没有这句话', 400);
    const text = String(item.text).slice(0, LIMITS.maxTtsChars);
    const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });
    const audio = await openai.audio.speech.create({
      model: 'gpt-4o-mini-tts',
      voice: 'coral',
      input: text,
      instructions: '用标准普通话，语气亲切、专业、自然，像一位耐心的职业顾问在和人聊天，语速适中。',
      response_format: 'mp3',
    });
    const buf = Buffer.from(await audio.arrayBuffer());
    await supabase.from('career_sessions').update({ tts_count: (s.tts_count || 0) + 1 }).eq('id', s.id);
    // 计费按时长估：中文约 4 字 / 秒，约 $0.015/分钟
    await addCost(s.id, s.cost_usd, (text.length / 4 / 60) * 0.015);
    return new Response(buf, { headers: { 'Content-Type': 'audio/mpeg', 'Cache-Control': 'no-store' } });
  } catch (e: any) {
    console.error('[career/tts]', e);
    return err('朗读失败', 500);
  }
}
/**
 * AI 职业访谈 · 语音转文字（游客可用）
 * POST multipart { sessionId, file } → { text }
 * 服务端调用 OpenAI 转写：国内用户不直连境外服务，浏览器自带的语音识别（连 Google）在国内用不了。
 */
import { NextResponse } from 'next/server';
import OpenAI, { toFile } from 'openai';
import { supabase } from '@/lib/supabase/client';
import { addCost, LIMITS, loadSession } from '@/lib/career/interview';
export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 60;
export async function POST(req: Request) {
  try {
    const fd = await req.formData();
    const s = await loadSession(fd.get('sessionId'));
    if (!s) return NextResponse.json({ error: '会话不存在' }, { status: 404 });
    if ((s.stt_count || 0) >= LIMITS.maxStt) return NextResponse.json({ error: '这次访谈的语音次数用完了，可以打字回答' }, { status: 429 });
    const file = fd.get('file');
    if (!file || typeof file === 'string' || file.size === 0) return NextResponse.json({ error: '没收到音频' }, { status: 400 });
    if (file.size > 10 * 1024 * 1024) return NextResponse.json({ error: '录音太长' }, { status: 400 });
    const mime = (file.type || 'audio/webm').split(';')[0];
    // 文件扩展名必须和真实格式一致，否则 OpenAI 会拒收（Chrome 录 webm，Safari / iPhone 录 mp4）
    const ext = mime.includes('mp4') || mime.includes('m4a') || mime.includes('aac') ? 'm4a'
      : mime.includes('mpeg') || mime.includes('mp3') ? 'mp3'
      : mime.includes('ogg') ? 'ogg' : mime.includes('wav') ? 'wav' : 'webm';
    const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });
    const r = await openai.audio.transcriptions.create({
      file: await toFile(Buffer.from(await file.arrayBuffer()), `voice.${ext}`, { type: mime }),
      model: 'gpt-4o-mini-transcribe',
      language: 'zh',
      prompt: '这是一段求职者在职业访谈中的口语回答，可能夹杂英文岗位名、公司名和技术词。',
    });
    const text = String(r.text || '').trim();
    await supabase.from('career_sessions').update({ stt_count: (s.stt_count || 0) + 1 }).eq('id', s.id);
    // 计费按时长估：opus 约 12KB/秒，$0.003/分钟
    await addCost(s.id, s.cost_usd, (file.size / 12000 / 60) * 0.003);
    return NextResponse.json({ text });
  } catch (e: any) {
    console.error('[career/stt]', e);
    return NextResponse.json({ error: '语音识别失败，可以再说一遍或打字回答' }, { status: 500 });
  }
}
/**
 * AI 职业访谈 · 开始（游客可用）
 * POST multipart { file? , text? } → 解析简历 → 简历画像 → 建会话
 * 返回 { sessionId, resume, profile }
 */
import { NextResponse } from 'next/server';
import { supabase } from '@/lib/supabase/client';
import { POST as parseResume } from '@/app/api/talent-audit/parse/route';
import { CAREER_MODEL_ID, careerComplete, clientIp, overDailyLimit, PROFILE_SYSTEM, resumeBrief, type Profile } from '@/lib/career/interview';
export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 120;
export async function POST(req: Request) {
  try {
    const ip = clientIp(req);
    if (await overDailyLimit(ip)) {
      return NextResponse.json({ error: '今天的体验次数用完了，明天再来吧' }, { status: 429 });
    }
    // 交给现成的简历解析（文件或粘贴文字都行）
    const fd = await req.formData();
    const forward = new FormData();
    const file = fd.get('file');
    const text = fd.get('text');
    if (file && typeof file !== 'string') {
      if (file.size > 8 * 1024 * 1024) return NextResponse.json({ error: '文件太大（超过 8MB）' }, { status: 400 });
      forward.append('file', file);
    }
    if (typeof text === 'string' && text.trim()) forward.append('text', text.slice(0, 20000));
    forward.append('modelId', CAREER_MODEL_ID);   // 简历解析用同一个模型
    const parsedRes = await parseResume(new Request(new URL('/api/talent-audit/parse', req.url), { method: 'POST', body: forward }));
    const parsed = await parsedRes.json();
    if (!parsedRes.ok || parsed?.error) return NextResponse.json({ error: parsed?.error || '简历解析失败' }, { status: 400 });
    const resume = parsed.resume || {};
    const { data: profile, cost } = await careerComplete<Profile>('profile', PROFILE_SYSTEM, `候选人简历：\n${resumeBrief(resume)}`, { temperature: 0.3 });
    const { data: row, error } = await supabase.from('career_sessions').insert({
      ip, user_agent: req.headers.get('user-agent')?.slice(0, 300) || null,
      resume, profile: profile || null, cost_usd: cost || 0,
    }).select('id').single();
    if (error || !row) throw new Error(error?.message || '会话创建失败');
    return NextResponse.json({ sessionId: row.id, resume, profile });
  } catch (e: any) {
    console.error('[career/start]', e);
    return NextResponse.json({ error: e?.message || '启动失败' }, { status: 500 });
  }
}

