// ── 二、访谈：朗读 → 聆听 → 转写 → 下一句 ──────────────────────
const speakBrowser = (text: string) => new Promise<void>((resolve) => {
  try {
    const synth = window.speechSynthesis;
    if (!synth) return resolve();
    synth.cancel();
    const u = new SpeechSynthesisUtterance(text);
    u.lang = 'zh-CN'; u.rate = 1.02;
    const zh = synth.getVoices().find((v) => /zh[-_]CN/i.test(v.lang));
    if (zh) u.voice = zh;
    u.onend = () => resolve(); u.onerror = () => resolve();
    synth.speak(u);
  } catch { resolve(); }
});

const speak = useCallback(async (index: number, text: string) => {
  setPhase('speaking');
  try {
    const res = await fetch('/api/career/tts', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ sessionId: sessionRef.current, index }) });
    if (!res.ok) throw new Error('tts');
    const url = URL.createObjectURL(await res.blob());
    const a = audioRef.current!;
    a.src = url;
    await new Promise<void>((resolve) => {
      a.onended = () => resolve(); a.onerror = () => resolve(); a.onpause = () => resolve();
      a.play().catch(() => resolve());
    });
    URL.revokeObjectURL(url);
  } catch {
    await speakBrowser(text);   // 服务端朗读失败：退回浏览器朗读
  }
}, []);
